import * as posedetection from '@tensorflow-models/pose-detection';
import * as tf from '@tensorflow/tfjs-core';
import * as dat from 'dat.gui';

import * as params from './params';

/**
 * Records each flag's default value under the runtime environment and is a
 * constant in runtime.
 */
let TUNABLE_FLAG_DEFAULT_VALUE_MAP;

let enableTrackingController;
let scoreThresholdController;
export let realSizeController;

const stringValueMap = {};
let backendFolder;

const SUPPORTS_LOCAL_STORAGE = function () {
  try { return !!window.localStorage; }
  catch (e) { return false; }
}();

function save() {
  if (!SUPPORTS_LOCAL_STORAGE) return;
  try {
    window.localStorage.setItem('STATE', JSON.stringify({
      renderDeltas: params.STATE.renderDeltas,
      calibration: {
        ear: {
          threshold: params.STATE.calibration.ear.threshold,
          ignore: params.STATE.calibration.ear.ignore,
        },
        shoulder: {
          threshold: params.STATE.calibration.shoulder.threshold,
          ignore: params.STATE.calibration.shoulder.ignore,
        },
        elbow: {
          threshold: params.STATE.calibration.elbow.threshold,
          ignore: params.STATE.calibration.elbow.ignore,
        },
        wrist: {
          threshold: params.STATE.calibration.wrist.threshold,
          ignore: params.STATE.calibration.wrist.ignore,
        },
        hip: {
          threshold: params.STATE.calibration.hip.threshold,
          ignore: params.STATE.calibration.hip.ignore,
        },
        knee: {
          threshold: params.STATE.calibration.knee.threshold,
          ignore: params.STATE.calibration.knee.ignore,
        },
        ankle: {
          threshold: params.STATE.calibration.ankle.threshold,
          ignore: params.STATE.calibration.ankle.ignore,
        },
      },
      camera: {
        targetFPS: params.STATE.camera.targetFPS,
        sizeOption: params.STATE.camera.sizeOption,
        facingMode: params.STATE.camera.facingMode,
      },
    }));
  } catch (e) { alert(`Failed to save to local storage due to ${e}`) }
}

async function load(gui) {
  if (!SUPPORTS_LOCAL_STORAGE) return;
  try {
    const state = window.localStorage.getItem('STATE');
    if (state == null) return;
    const object = JSON.parse(state);
    params.STATE.renderDeltas = object.renderDeltas;
    params.STATE.calibration.ear.threshold = object.calibration.ear.threshold;
    params.STATE.calibration.ear.ignore = object.calibration.ear.ignore;
    params.STATE.calibration.shoulder.threshold = object.calibration.shoulder.threshold;
    params.STATE.calibration.shoulder.ignore = object.calibration.shoulder.ignore;
    params.STATE.calibration.elbow.threshold = object.calibration.elbow.threshold;
    params.STATE.calibration.elbow.ignore = object.calibration.elbow.ignore;
    params.STATE.calibration.wrist.threshold = object.calibration.wrist.threshold;
    params.STATE.calibration.wrist.ignore = object.calibration.wrist.ignore;
    params.STATE.calibration.hip.threshold = object.calibration.hip.threshold;
    params.STATE.calibration.hip.ignore = object.calibration.hip.ignore;
    params.STATE.calibration.knee.threshold = object.calibration.knee.threshold;
    params.STATE.calibration.knee.ignore = object.calibration.knee.ignore;
    params.STATE.calibration.ankle.threshold = object.calibration.ankle.threshold;
    params.STATE.calibration.ankle.ignore = object.calibration.ankle.ignore;
    params.STATE.camera.targetFPS = object.camera.targetFPS;
    params.STATE.camera.sizeOption = object.camera.sizeOption;
    params.STATE.camera.facingMode = object.camera.facingMode;
    params.STATE.calcLUT();
    params.STATE.isTargetFPSChanged = true;
    params.STATE.isSizeOptionChanged = true;
    params.STATE.isFacingModeChanged = true;
    gui.domElement.remove();
    (await setupDatGui()).open();
  } catch (e) { alert(`Failed to load from local storage due to ${e}`) }
}

function clear() {
  if (!SUPPORTS_LOCAL_STORAGE) return;
  try { window.localStorage.removeItem('STATE'); }
  catch (e) { alert(`Failed to clear local storage due to ${e}`) }
}

export async function setupDatGui() {
  const gui = new dat.GUI({ width: 300 });
  const guiElem = document.getElementById('gui');
  guiElem.append(gui.domElement);

  const buttonSave = document.createElement('button');
  buttonSave.innerHTML = 'Save'
  buttonSave.onclick = function () { save(); }
  const buttonLoad = document.createElement('button');
  buttonLoad.innerHTML = 'Load'
  buttonLoad.onclick = function () { load(gui); }
  const buttonClear = document.createElement('button');
  buttonClear.innerHTML = 'Clear'
  buttonClear.onclick = function () { clear(); }
  const storageController = gui.add({ buttons: true }, 'buttons')
  storageController.domElement.previousElementSibling.innerHTML = ''
  if (SUPPORTS_LOCAL_STORAGE) {
    storageController.domElement.innerHTML = ''
    storageController.domElement.appendChild(buttonSave)
    storageController.domElement.appendChild(buttonLoad)
    storageController.domElement.appendChild(buttonClear)
  } else { storageController.domElement.innerHTML = 'No support for local storage, can not save.' }
  storageController.domElement.style = 'text-align: center; width: 100%'

  const buttonPrint = document.createElement('button');
  buttonPrint.innerHTML = 'Print'
  buttonPrint.onclick = function () { print(); }
  const buttonExport = document.createElement('button');
  buttonExport.innerHTML = 'Export'
  buttonExport.onclick = function () { alert(JSON.stringify(params.STATE.calibration, null, 2)); }
  const outputController = gui.add({ buttons: true }, 'buttons')
  outputController.domElement.previousElementSibling.innerHTML = ''
  outputController.domElement.innerHTML = ''
  outputController.domElement.appendChild(buttonPrint)
  outputController.domElement.appendChild(buttonExport)
  outputController.domElement.style = 'text-align: center; width: 100%'

  const estimateController = gui.add(params.STATE, 'estimate');
  const useDeviceOrientationController = gui.add(params.STATE, 'useDeviceOrientation');

  if (params.STATE.dev) {
    const renderController = gui.add(params.STATE, 'render');
    const useDeviceOrientationQuaternionController = gui.add(params.STATE, 'useDeviceOrientationQuaternion');
    const useDeviceOrientationAbsoluteController = gui.add(params.STATE, 'useDeviceOrientationAbsolute');
    const useDeviceOrientationAxisController = gui.add(params.STATE, 'useDeviceOrientationAxis', ['alpha', 'beta', 'gamma']);
    const useDeviceOrientationAxisOffsetController = gui.add(params.STATE, 'useDeviceOrientationAxisOffset', -180, 180);
    const targetOrientationSideThresholdController = gui.add(params.STATE, 'targetOrientationSideThreshold', 1, 12);
    const targetOrientationFaceThresholdController = gui.add(params.STATE, 'targetOrientationFaceThreshold', 1, 9);
    const renderCorrectionController = gui.add(params.STATE, 'renderCorrection');
    const useCorrectionController = gui.add(params.STATE, 'useCorrection');
    const draw2DFrom3DController = gui.add(params.STATE, 'draw2DFrom3D');
    const bufferLengthController = gui.add(params.STATE, 'bufferLength');
    const seekThresholdController = gui.add(params.STATE.seek, 'threshold', 0, 33);
    const seekCooldownController = gui.add(params.STATE.seek, 'cooldown', 0, 5000);
    bufferLengthController.onFinishChange(_ => { params.STATE.initBuffers(); });
  } else gui.close();

  const calibrationFolder = gui.addFolder('Calibration');
  const renderDeltasController = calibrationFolder.add(params.STATE, 'renderDeltas')
  const earThresholdController = calibrationFolder.add(params.STATE.calibration.ear, 'threshold', 0, 10)
  earThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ear threshold %";
  const earIgnoreController = calibrationFolder.add(params.STATE.calibration.ear, 'ignore')
  earIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore ear";
  const shoulderThresholdController = calibrationFolder.add(params.STATE.calibration.shoulder, 'threshold', 0, 10)
  shoulderThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "shoulder threshold %";
  const shoulderIgnoreController = calibrationFolder.add(params.STATE.calibration.shoulder, 'ignore')
  shoulderIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore shoulder";
  const elbowThresholdController = calibrationFolder.add(params.STATE.calibration.elbow, 'threshold', 0, 10)
  elbowThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "elbow threshold %";
  const elbowIgnoreController = calibrationFolder.add(params.STATE.calibration.elbow, 'ignore')
  elbowIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore elbow";
  const wristThresholdController = calibrationFolder.add(params.STATE.calibration.wrist, 'threshold', 0, 10)
  wristThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "wrist threshold %";
  const wristIgnoreController = calibrationFolder.add(params.STATE.calibration.wrist, 'ignore')
  wristIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore wrist";
  const hipThresholdController = calibrationFolder.add(params.STATE.calibration.hip, 'threshold', 0, 10)
  hipThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "hip threshold %";
  const hipIgnoreController = calibrationFolder.add(params.STATE.calibration.hip, 'ignore')
  hipIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore hip";
  const kneeThresholdController = calibrationFolder.add(params.STATE.calibration.knee, 'threshold', 0, 10)
  kneeThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "knee threshold %";
  const kneeIgnoreController = calibrationFolder.add(params.STATE.calibration.knee, 'ignore')
  kneeIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore knee";
  const ankleThresholdController = calibrationFolder.add(params.STATE.calibration.ankle, 'threshold', 0, 10)
  ankleThresholdController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ankle threshold %";
  const ankleIgnoreController = calibrationFolder.add(params.STATE.calibration.ankle, 'ignore')
  ankleIgnoreController.onFinishChange(_ => { params.STATE.calcLUT(); }).domElement.previousElementSibling.innerHTML = "ignore ankle";
  calibrationFolder.open();

  // The camera folder contains options for video settings.
  const cameraFolder = gui.addFolder('Camera');
  const fpsController = cameraFolder.add(params.STATE.camera, 'targetFPS');
  fpsController.onFinishChange(_ => { params.STATE.isTargetFPSChanged = true; });
  const sizeController = cameraFolder.add(params.STATE.camera, 'sizeOption', Object.keys(params.VIDEO_SIZE));
  sizeController.onChange(_ => { params.STATE.isSizeOptionChanged = true; });
  realSizeController = cameraFolder.add(params.STATE.camera, 'realSize');
  const items = params.STATE.dev ? ['user', 'environment', 'left', 'right'] : ['user', 'environment'];
  const facingModeController = cameraFolder.add(params.STATE.camera, 'facingMode', items);
  facingModeController.onChange(_ => { params.STATE.isFacingModeChanged = true; });
  cameraFolder.open();

  // The model folder contains options for model selection.
  const modelFolder = gui.addFolder('Model');

  const model = 'blazepose';
  let type = null;

  switch (model) {
    case 'posenet':
      params.STATE.model = posedetection.SupportedModels.PoseNet;
      break;
    case 'movenet':
      params.STATE.model = posedetection.SupportedModels.MoveNet;
      if (type !== 'lightning' && type !== 'thunder' && type !== 'multipose') {
        // Nulify invalid value.
        type = null;
      }
      break;
    case 'blazepose':
      params.STATE.model = posedetection.SupportedModels.BlazePose;
      if (type !== 'full' && type !== 'lite' && type !== 'heavy') {
        // Nulify invalid value.
        type = null;
      }
      break;
  }

  const modelController = modelFolder.add(params.STATE, 'model', Object.values(posedetection.SupportedModels));
  modelController.onChange(_ => {
    params.STATE.isModelChanged = true;
    showModelConfigs(modelFolder);
    showBackendConfigs(backendFolder);
  });

  showModelConfigs(modelFolder, type);

  modelFolder.open();

  backendFolder = gui.addFolder('Backend');

  showBackendConfigs(backendFolder);

  backendFolder.open();

  if (params.STATE.dev) return gui;

  gui.removeFolder(modelFolder);
  gui.removeFolder(backendFolder);

  return gui;
}

export async function showBackendConfigs(folderController) {
  if (folderController == null) {
    folderController = backendFolder;
  }
  // Clean up backend configs for the previous model.
  const fixedSelectionCount = 0;
  while (folderController.__controllers.length > fixedSelectionCount) {
    folderController.remove(
      folderController
        .__controllers[folderController.__controllers.length - 1]);
  }
  const backends = params.MODEL_BACKEND_MAP[params.STATE.model];
  if (params.STATE.backend == null) {
    // The first element of the array is the default backend for the model.
    params.STATE.backend = backends[0];
  }
  const backendController = folderController.add(params.STATE, 'backend', backends);
  backendController.name('runtime-backend');
  backendController.onChange(async backend => {
    params.STATE.isBackendChanged = true;
    await showFlagSettings(folderController, backend);
  });
  await showFlagSettings(folderController, params.STATE.backend);
}

function showModelConfigs(folderController, type) {
  // Clean up model configs for the previous model.
  // The first constroller under the `folderController` is the model
  // selection.
  const fixedSelectionCount = 1;
  while (folderController.__controllers.length > fixedSelectionCount) {
    folderController.remove(
      folderController
        .__controllers[folderController.__controllers.length - 1]);
  }

  switch (params.STATE.model) {
    case posedetection.SupportedModels.PoseNet:
      addPoseNetControllers(folderController);
      break;
    case posedetection.SupportedModels.MoveNet:
      addMoveNetControllers(folderController, type);
      break;
    case posedetection.SupportedModels.BlazePose:
      addBlazePoseControllers(folderController, type);
      break;
    default:
      alert(`Model ${params.STATE.model} is not supported.`);
  }
}

// The PoseNet model config folder contains options for PoseNet config
// settings.
function addPoseNetControllers(modelConfigFolder) {
  params.STATE.modelConfig = { ...params.POSENET_CONFIG };

  const maxPosesController = modelConfigFolder.add(params.STATE.modelConfig, 'maxPoses', [1, 2, 3, 4, 5]);
  scoreThresholdController = modelConfigFolder.add(params.STATE.modelConfig, 'scoreThreshold', 0, 1);
}

// The MoveNet model config folder contains options for MoveNet config
// settings.
function addMoveNetControllers(modelConfigFolder, type) {
  params.STATE.modelConfig = { ...params.MOVENET_CONFIG };
  params.STATE.modelConfig.type = type != null ? type : 'lightning';

  // Set multipose defaults on initial page load.
  if (params.STATE.modelConfig.type === 'multipose') {
    params.STATE.modelConfig.enableTracking = true;
    params.STATE.modelConfig.scoreThreshold = 0.2;
  }

  const typeController = modelConfigFolder.add(params.STATE.modelConfig, 'type', ['lightning', 'thunder', 'multipose']);
  typeController.onChange(type => {
    // Set isModelChanged to true, so that we don't render any result during changing models.
    params.STATE.isModelChanged = true;
    if (type === 'multipose') {
      // Defaults to enable tracking for multi pose.
      if (enableTrackingController) enableTrackingController.setValue(true);
      // Defaults to a lower scoreThreshold for multi pose.
      if (scoreThresholdController) scoreThresholdController.setValue(0.2);
    } else enableTrackingController.setValue(false);
  });
  const customModelController = modelConfigFolder.add(params.STATE.modelConfig, 'customModel');
  customModelController.onFinishChange(_ => { params.STATE.isModelChanged = true; });
  scoreThresholdController = modelConfigFolder.add(params.STATE.modelConfig, 'scoreThreshold', 0, 1);
  enableTrackingController = modelConfigFolder.add(params.STATE.modelConfig, 'enableTracking',);
  // Set isModelChanged to true, so that we don't render any result during changing models.
  enableTrackingController.onChange(_ => { params.STATE.isModelChanged = true; })
}

// The BlazePose model config folder contains options for BlazePose config
// settings.
function addBlazePoseControllers(modelConfigFolder, type) {
  params.STATE.modelConfig = { ...params.BLAZEPOSE_CONFIG };
  params.STATE.modelConfig.type = type != null ? type : 'full';

  const typeController = modelConfigFolder.add(params.STATE.modelConfig, 'type', ['lite', 'full', 'heavy']);
  // Set isModelChanged to true, so that we don't render any result during changing models.
  typeController.onChange(_ => { params.STATE.isModelChanged = true; });

  const enableSmoothingController = modelConfigFolder.add(params.STATE.modelConfig, 'enableSmoothing');
  enableSmoothingController.onChange(_ => { params.STATE.isModelChanged = true; });

  const enableSegmentationController = modelConfigFolder.add(params.STATE.modelConfig, 'enableSegmentation');
  enableSegmentationController.onChange(_ => { params.STATE.isModelChanged = true; });

  const smoothSegmentationController = modelConfigFolder.add(params.STATE.modelConfig, 'smoothSegmentation');
  smoothSegmentationController.onChange(_ => { params.STATE.isModelChanged = true; });

  const renderSegmentationController = modelConfigFolder.add(params.STATE.modelConfig, 'renderSegmentation');

  scoreThresholdController = modelConfigFolder.add(params.STATE.modelConfig, 'scoreThreshold', 0, 1);

  const render3DController = modelConfigFolder.add(params.STATE.modelConfig, 'render3D');
  render3DController.onChange(render3D => { document.querySelector('#scatter-gl-container').style.display = render3D ? 'inline-block' : 'none'; });
}

/**
 * Query all tunable flags' default value and populate `STATE.flags` with them.
 */
async function initDefaultValueMap() {
  // Clean up the cache to query tunable flags' default values.
  TUNABLE_FLAG_DEFAULT_VALUE_MAP = {};
  params.STATE.flags = {};
  for (const backend in params.BACKEND_FLAGS_MAP) {
    for (let index = 0; index < params.BACKEND_FLAGS_MAP[backend].length;
      index++) {
      const flag = params.BACKEND_FLAGS_MAP[backend][index];
      TUNABLE_FLAG_DEFAULT_VALUE_MAP[flag] = await tf.env().getAsync(flag);
    }
  }

  // Initialize STATE.flags with tunable flags' default values.
  for (const flag in TUNABLE_FLAG_DEFAULT_VALUE_MAP) {
    if (params.BACKEND_FLAGS_MAP[params.STATE.backend].indexOf(flag) > -1) {
      params.STATE.flags[flag] = TUNABLE_FLAG_DEFAULT_VALUE_MAP[flag];
    }
  }
}

/**
 * Heuristically determine flag's value range based on flag's default value.
 *
 * Assume that the flag's default value has already chosen the best option for
 * the runtime environment, so users can only tune the flag value downwards.
 *
 * For example, if the default value of `WEBGL_RENDER_FLOAT32_CAPABLE` is false,
 * the tunable range is [false]; otherwise, the tunable range is [true. false].
 *
 * @param {string} flag
 */
function getTunableRange(flag) {
  const defaultValue = TUNABLE_FLAG_DEFAULT_VALUE_MAP[flag];
  if (flag === 'WEBGL_FORCE_F16_TEXTURES') {
    return [false, true];
  } else if (flag === 'WEBGL_VERSION') {
    const tunableRange = [];
    for (let value = 1; value <= defaultValue; value++) {
      tunableRange.push(value);
    }
    return tunableRange;
  } else if (flag === 'WEBGL_FLUSH_THRESHOLD') {
    const tunableRange = [-1];
    for (let value = 0; value <= 2; value += 0.25) {
      tunableRange.push(value);
    }
    return tunableRange;
  } else if (typeof defaultValue === 'boolean') {
    return defaultValue ? [false, true] : [false];
  } else if (params.TUNABLE_FLAG_VALUE_RANGE_MAP[flag] != null) {
    return params.TUNABLE_FLAG_VALUE_RANGE_MAP[flag];
  } else {
    return [defaultValue];
  }
}

/**
 * Show flag settings for the given backend under the UI element of
 * `folderController`.
 *
 * @param {dat.gui.GUI} folderController
 * @param {string} backendName
 */
function showBackendFlagSettings(folderController, backendName) {
  const tunableFlags = params.BACKEND_FLAGS_MAP[backendName];
  for (let index = 0; index < tunableFlags.length; index++) {
    const flag = tunableFlags[index];
    const flagName = params.TUNABLE_FLAG_NAME_MAP[flag] || flag;

    // When tunable (bool) and range (array) attributes of `flagRegistry` is implemented, we can apply them to here.
    const flagValueRange = getTunableRange(flag);
    // Heuristically consider a flag with at least two options as tunable.
    if (flagValueRange.length < 2) {
      console.warn(`The ${flag} is considered as untunable, because its value range is [${flagValueRange}].`);
      continue;
    }

    let flagController;
    if (typeof flagValueRange[0] === 'boolean') {
      // Show checkbox for boolean flags.
      flagController = folderController.add(params.STATE.flags, flag);
    } else {
      // Show dropdown for other types of flags.
      flagController = folderController.add(params.STATE.flags, flag, flagValueRange);
      // Because dat.gui always casts dropdown option values to string we need `stringValueMap` and `onFinishChange()` to recover the value type.
      if (stringValueMap[flag] == null) {
        stringValueMap[flag] = {};
        for (let index = 0; index < flagValueRange.length; index++) {
          const realValue = flagValueRange[index];
          const stringValue = String(flagValueRange[index]);
          stringValueMap[flag][stringValue] = realValue;
        }
      }
      flagController.onFinishChange(stringValue => { params.STATE.flags[flag] = stringValueMap[flag][stringValue]; });
    }
    flagController.name(flagName).onChange(() => { params.STATE.isFlagChanged = true; });
  }
}

/**
 * Set up flag settings under the UI element of `folderController`:
 * - If it is the first call, initialize the flags' default value and show flag
 * settings for both the general and the given backend.
 * - Else, clean up flag settings for the previous backend and show flag
 * settings for the new backend.
 *
 * @param {dat.gui.GUI} folderController
 * @param {string} backendName
 */
async function showFlagSettings(folderController, backendName) {
  await initDefaultValueMap();

  // Clean up flag settings for the previous backend.
  // The first constroller under the `folderController` is the backend
  // setting.
  const fixedSelectionCount = 1;
  while (folderController.__controllers.length > fixedSelectionCount) {
    folderController.remove(
      folderController
        .__controllers[folderController.__controllers.length - 1]);
  }

  // Show flag settings for the new backend.
  showBackendFlagSettings(folderController, backendName);
}
