export class CircularBuffer {
  constructor(length) {
    this.data = Array(length > 0 ? length : 1).fill(0)
    this.current = 0
    this.average = 0
  }

  add(value) {
    this.data[this.current++] = value
    if (this.current >= this.data.length) this.current = 0
    this.average = this.data.reduce((a, b) => a + b) / this.data.length
  }
}
