import { setBackendAndEnvFlags, isiOS, isMobile } from './util';

let detector, camera;
let rafId;
let renderer = null;
let useGpuRenderer = false;

async function createDetector() {
  switch (STATE.model) {
    case posedetection.SupportedModels.PoseNet:
      return posedetection.createDetector(STATE.model, {
        quantBytes: 4,
        architecture: 'MobileNetV1',
        outputStride: 16,
        inputResolution: { width: 500, height: 500 },
        multiplier: 0.75
      });
    case posedetection.SupportedModels.BlazePose:
      const runtime = STATE.backend.split('-')[0];
      if (runtime === 'mediapipe') {
        return posedetection.createDetector(STATE.model, {
          runtime,
          modelType: STATE.modelConfig.type,
          enableSmoothing: STATE.modelConfig.enableSmoothing,
          enableSegmentation: STATE.modelConfig.enableSegmentation,
          smoothSegmentation: STATE.modelConfig.smoothSegmentation,
          solutionPath: `https://cdn.jsdelivr.net/npm/@mediapipe/pose@${mpPose.VERSION}`
        });
      } else if (runtime === 'tfjs') {
        return posedetection.createDetector(STATE.model, {
          runtime,
          modelType: STATE.modelConfig.type,
          enableSmoothing: STATE.modelConfig.enableSmoothing,
          enableSegmentation: STATE.modelConfig.enableSegmentation,
          smoothSegmentation: STATE.modelConfig.smoothSegmentation
        });
      }
    case posedetection.SupportedModels.MoveNet:
      let modelType;
      if (STATE.modelConfig.type == 'lightning') {
        modelType = posedetection.movenet.modelType.SINGLEPOSE_LIGHTNING;
      } else if (STATE.modelConfig.type == 'thunder') {
        modelType = posedetection.movenet.modelType.SINGLEPOSE_THUNDER;
      } else if (STATE.modelConfig.type == 'multipose') {
        modelType = posedetection.movenet.modelType.MULTIPOSE_LIGHTNING;
      }
      const modelConfig = { modelType };

      if (STATE.modelConfig.customModel !== '') {
        modelConfig.modelUrl = STATE.modelConfig.customModel;
      }
      if (STATE.modelConfig.type === 'multipose') {
        modelConfig.enableTracking = STATE.modelConfig.enableTracking;
      }
      return posedetection.createDetector(STATE.model, modelConfig);
  }
}

async function checkGuiUpdate() {
  if (STATE.isTargetFPSChanged || STATE.isSizeOptionChanged || STATE.isFacingModeChanged) {
    camera.video.srcObject.getTracks().forEach(track => track.stop());
    camera = await Camera.setup(STATE.camera);
    if (STATE.isFacingModeChanged && !useGpuRenderer && renderer) renderer.flip(renderer.videoWidth, renderer.videoHeight);
    STATE.isTargetFPSChanged = false;
    STATE.isSizeOptionChanged = false;
    STATE.isFacingModeChanged = false;
    renderer.scale = { x: renderer.canvas.width / camera.video.width, y: renderer.canvas.height / camera.video.height }
  }

  if (STATE.isModelChanged || STATE.isFlagChanged || STATE.isBackendChanged) {
    STATE.isModelChanged = true;

    window.cancelAnimationFrame(rafId);

    if (detector != null) {
      detector.dispose();
    }

    if (STATE.isFlagChanged || STATE.isBackendChanged) {
      await setBackendAndEnvFlags(STATE.flags, STATE.backend);
    }

    try {
      detector = await createDetector(STATE.model);
    } catch (error) {
      detector = null;
      alert(error);
    }

    STATE.isFlagChanged = false;
    STATE.isBackendChanged = false;
    STATE.isModelChanged = false;
  }

  if (realSizeController) realSizeController.setValue(`${camera.video.width} X ${camera.video.height}`);
}

function beginEstimatePosesStats(stats) {
  stats.startInferenceTime = (performance || Date).now();
}

function endEstimatePosesStats(stats) {
  const endInferenceTime = (performance || Date).now();
  stats.inferenceTimeSum += endInferenceTime - stats.startInferenceTime;
  ++stats.numInferences;

  const panelUpdateMilliseconds = 1000;
  if (endInferenceTime - stats.lastPanelUpdate >= panelUpdateMilliseconds) {
    const averageInferenceTime = stats.inferenceTimeSum / stats.numInferences;
    stats.inferenceTimeSum = 0;
    stats.numInferences = 0;
    stats.customFpsPanel.update(1000.0 / averageInferenceTime, 120);
    stats.lastPanelUpdate = endInferenceTime;
  }
}

const estimatePosesStats = {
  startInferenceTime: 0,
  inferenceTimeSum: 0,
  numInferences: 0,
  lastPanelUpdate: 0,
  customFpsPanel: null,
}

const renderResultStats = {
  startInferenceTime: 0,
  inferenceTimeSum: 0,
  numInferences: 0,
  lastPanelUpdate: 0,
  customFpsPanel: null,
}

async function estimatePoses() {
  let poses = null;
  let canvasInfo = null;

  // FPS only counts the time it takes to finish estimatePoses.
  beginEstimatePosesStats(estimatePosesStats);

  if (useGpuRenderer && STATE.model !== 'PoseNet') {
    throw new Error('Only PoseNet supports GPU renderer!');
  }
  // Detectors can throw errors, for example when using custom URLs that
  // contain a model that doesn't provide the expected output.
  try {
    if (useGpuRenderer) {
      const [posesTemp, canvasInfoTemp] = await detector.estimatePosesGPU(
        camera.video,
        { maxPoses: STATE.modelConfig.maxPoses, flipHorizontal: false },
        true);
      poses = structuredClone(posesTemp);
      canvasInfo = structuredClone(canvasInfoTemp);
    } else {
      poses = await detector.estimatePoses(
        camera.video,
        { maxPoses: STATE.modelConfig.maxPoses, flipHorizontal: false });
    }
  } catch (error) {
    detector.dispose();
    detector = null;
    alert(error);
  }

  endEstimatePosesStats(estimatePosesStats);

  lastEstimate.poses = poses;
  lastEstimate.canvasInfo = canvasInfo;
  lastEstimate.inProgress = false;
  if (countKeypoints(poses) < STATE.seek.threshold) lastEstimate.cooldown = Date.now() + STATE.seek.cooldown;
  else if (lastEstimate.centerElem) lastEstimate.centerElem.innerHTML = null;
}

function countKeypoints(poses) {
  let keypointsNum = 0;
  if (!poses || poses.length <= 0) return keypointsNum;
  const scoreThreshold = STATE.modelConfig.scoreThreshold || 0;
  for (const pose of poses) {
    if (!pose.keypoints) continue;
    for (const keypoint of pose.keypoints) {
      const score = keypoint.score != null ? keypoint.score : 1;
      if (score >= scoreThreshold) keypointsNum++;
    }
  }
  return keypointsNum;
}

const TargetOrientation = {
  LEFT: "LEFT",
  RIGHT: "RIGHT",
  FRONT: "FRONT",
  BACK: "BACK",
  NONE: "NONE",
};

const lastDeviceOrientation = {
  gotDeviceOrientation: null,
  msg: "",
  alpha: 0,
  beta: 0,
  gamma: 0,
  quaternion: [0, 0, 0, 0],
  euler: [0, 0, 0],
  angle: 0,
  statusElem: null,
  targetOrientation: TargetOrientation.NONE,
}

const faceNames = ["mouth_left", "mouth_right", "left_eye_inner", "left_eye", "left_eye_outer", "right_eye_inner", "right_eye", "right_eye_outer", "nose"]

function getTargetOrientation(poses) {
  lastDeviceOrientation.targetOrientation = TargetOrientation.NONE;
  if (!poses || poses.length <= 0) return;
  const scoreThreshold = STATE.modelConfig.scoreThreshold || 0;
  for (const pose of poses) {
    if (!pose.keypoints || pose.keypoints.length <= 0) continue;
    const left = [];
    const right = [];
    const face = [];
    for (const keypoint of pose.keypoints) {
      const score = keypoint.score != null ? keypoint.score : 1;
      if (score < scoreThreshold) continue;
      if (faceNames.includes(keypoint.name)) face.push(keypoint);
      else if (keypoint.name.startsWith("left")) left.push(keypoint);
      else right.push(keypoint);
    }
    const delta = Math.abs(left.length - right.length)
    if (delta >= STATE.targetOrientationSideThreshold) lastDeviceOrientation.targetOrientation = left.length > right.length ? TargetOrientation.LEFT : TargetOrientation.RIGHT;
    else lastDeviceOrientation.targetOrientation = face.length >= STATE.targetOrientationFaceThreshold ? TargetOrientation.FRONT : TargetOrientation.BACK;
  }
}

const angleCorners = [
  ["left_shoulder", "right_shoulder", "left_elbow", "right_elbow"],
  ["left_shoulder", "right_shoulder", "left_hip", "right_hip"],
  ["left_shoulder", "right_shoulder", "left_knee", "right_knee"],
  ["left_elbow", "right_elbow", "left_hip", "right_hip"],
  ["left_elbow", "right_elbow", "left_knee", "right_knee"],
  ["left_hip", "right_hip", "left_knee", "right_knee"],
]

function getAngle(topLeft, topRight, botLeft, botRight) {
  const topX = (topLeft.x + topRight.x) / 2;
  const topY = (topLeft.y + topRight.y) / 2;
  const botX = (botLeft.x + botRight.x) / 2;
  const botY = (botLeft.y + botRight.y) / 2;
  const deltaX = topX - botX;
  const deltaY = topY - botY;
  const rad = Math.tan(deltaX / deltaY);
  const deg = rad * radtodeg
  return deg;
}

function correctPoseOrientation(poses) {
  if (!poses || poses.length <= 0) return;
  if (!lastDeviceOrientation.gotDeviceOrientation) {
    if (![TargetOrientation.FRONT, TargetOrientation.BACK].includes(lastDeviceOrientation.targetOrientation)) {
      if (lastDeviceOrientation.statusElem) lastDeviceOrientation.statusElem.innerHTML = `${lastDeviceOrientation.msg}: neither FRONT nor BACK, can't track - ${lastDeviceOrientation.targetOrientation}`;
      return;
    }
    const angles = []
    for (const pose of poses) {
      if (!pose.keypoints) continue;
      const keypoints = {};
      for (const keypoint of pose.keypoints) keypoints[keypoint.name] = keypoint;
      const scoreThreshold = STATE.modelConfig.scoreThreshold || 0;
      for (const corners of angleCorners) {
        let passed = 0;
        for (const corner of corners) {
          const keypoint = keypoints[corner];
          if (!keypoint) break;
          const score = keypoint.score != null ? keypoint.score : 1;
          if (score >= scoreThreshold) passed++;
          else break;
        }
        if (passed >= 4) angles.push(getAngle(keypoints[corners[0]], keypoints[corners[1]], keypoints[corners[2]], keypoints[corners[3]]));
      }
      break;
    }
    if (angles.length <= 0) return;
    let sum = 0;
    for (const angle of angles) sum += angle;
    lastDeviceOrientation.angle = -sum / angles.length;
  }
  if (lastDeviceOrientation.statusElem) lastDeviceOrientation.statusElem.innerHTML = `${lastDeviceOrientation.msg}: ${(lastDeviceOrientation.angle || 0).toFixed(2)} - ${lastDeviceOrientation.targetOrientation}`;
  const rad = -lastDeviceOrientation.angle * degtorad;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  for (const pose of poses) {
    if (!pose.keypoints) continue;
    for (const keypoint of pose.keypoints) {
      const x = keypoint.x;
      const y = keypoint.y;
      keypoint.correctedX = x * cos - y * sin;
      keypoint.correctedY = x * sin + y * cos;
    }
  }
}

const degtorad = Math.PI / 180;
const radtodeg = 180 / Math.PI;

function getQuaternion(alpha, beta, gamma) {
  // https://www.w3.org/TR/orientation-event/#example-8f884833

  const _x = beta ? beta * degtorad : 0;
  const _y = gamma ? gamma * degtorad : 0;
  const _z = alpha ? alpha * degtorad : 0;

  const cX = Math.cos(_x / 2);
  const cY = Math.cos(_y / 2);
  const cZ = Math.cos(_z / 2);
  const sX = Math.sin(_x / 2);
  const sY = Math.sin(_y / 2);
  const sZ = Math.sin(_z / 2);

  const w = cX * cY * cZ - sX * sY * sZ;
  const x = sX * cY * cZ - cX * sY * sZ;
  const y = cX * sY * cZ + sX * cY * sZ;
  const z = cX * cY * sZ + sX * sY * cZ;

  return [w, x, y, z];
}

function getEulerAngles(quaternion) {
  // https://en.wikipedia.org/wiki/Conversion_between_quaternions_and_Euler_angles

  const [_w, _x, _y, _z] = quaternion;

  const sinr_cosp = 2 * (_w * _x + _y * _z);
  const cosr_cosp = 1 - 2 * (_x * _x + _y * _y);
  const x = radtodeg * Math.atan2(sinr_cosp, cosr_cosp);

  const sinp = Math.sqrt(1 + 2 * (_w * _y - _x * _z));
  const cosp = Math.sqrt(1 - 2 * (_w * _y - _x * _z));
  const y = radtodeg * 2 * Math.atan2(sinp, cosp) - Math.PI / 2;

  const siny_cosp = 2 * (_w * _z + _x * _y);
  const cosy_cosp = 1 - 2 * (_y * _y + _z * _z);
  const z = radtodeg * Math.atan2(siny_cosp, cosy_cosp);

  return [x, y, z];
}

function deviceOrientationHandler(event) {
  if (event.absolute != STATE.useDeviceOrientationAbsolute) return;
  lastDeviceOrientation.alpha = event.alpha;
  lastDeviceOrientation.beta = event.beta;
  lastDeviceOrientation.gamma = event.gamma;
  lastDeviceOrientation.angle = lastDeviceOrientation[STATE.useDeviceOrientationAxis] + STATE.useDeviceOrientationAxisOffset;
  if (lastDeviceOrientation.angle <= -45) lastDeviceOrientation.angle += 90;
  else if (lastDeviceOrientation.angle >= 45) lastDeviceOrientation.angle -= 90;
  if (!STATE.useDeviceOrientationQuaternion) return;
  lastDeviceOrientation.quaternion = getQuaternion(event.alpha, event.beta, event.gamma)
  lastDeviceOrientation.euler = getEulerAngles(lastDeviceOrientation.quaternion);
  [lastDeviceOrientation.alpha, lastDeviceOrientation.beta, lastDeviceOrientation.gamma] = lastDeviceOrientation.euler;
  lastDeviceOrientation.angle = lastDeviceOrientation[STATE.useDeviceOrientationAxis] + STATE.useDeviceOrientationAxisOffset;
  if (lastDeviceOrientation.angle <= -45) lastDeviceOrientation.angle += 90;
  else if (lastDeviceOrientation.angle >= 45) lastDeviceOrientation.angle -= 90;
}

function addDeviceOrientationHandler(event, msg) {
  if (lastDeviceOrientation.gotDeviceOrientation) return;
  window.addEventListener(event, deviceOrientationHandler, true);
  lastDeviceOrientation.gotDeviceOrientation = true;
  lastDeviceOrientation.msg = msg
  if (lastDeviceOrientation.statusElem) lastDeviceOrientation.statusElem.innerHTML = msg;
}

function removeDeviceOrientationHandler(event, msg) {
  if (lastDeviceOrientation.gotDeviceOrientation != null && !lastDeviceOrientation.gotDeviceOrientation) return;
  window.removeEventListener(event, deviceOrientationHandler, true);
  lastDeviceOrientation.gotDeviceOrientation = false;
  lastDeviceOrientation.msg = msg
  if (lastDeviceOrientation.statusElem) lastDeviceOrientation.statusElem.innerHTML = msg;
}

async function manageDeviceOrientationHandler() {
  const event = STATE.useDeviceOrientationAbsolute ? "deviceorientationabsolute" : "deviceorientation";
  if (!STATE.useDeviceOrientation) { removeDeviceOrientationHandler(event, "Disabled, tracking estimation stream"); return; }
  if (!isMobile()) { removeDeviceOrientationHandler(event, "Not mobile, tracking estimation stream"); return; }
  if (!window.DeviceOrientationEvent) { removeDeviceOrientationHandler(event, "Not supported, tracking estimation stream"); return; }
  if (!isiOS()) { addDeviceOrientationHandler(event, "Android, using sensor"); return; }
  await DeviceOrientationEvent.requestPermission().then(response => {
    if (response === "granted") addDeviceOrientationHandler(event, "Apple, using sensor");
    else removeDeviceOrientationHandler(event, "Apple, no permission");
  }).catch(() => removeDeviceOrientationHandler(event, "Apple, not supported"));
}

const lastEstimate = {
  poses: [],
  canvasInfo: null,
  inProgress: false,
  cooldown: 0,
  centerElem: null,
}

async function renderResult() {
  beginEstimatePosesStats(renderResultStats);
  if (camera.video.readyState < 2) {
    await new Promise((resolve) => {
      camera.video.onloadeddata = () => {
        resolve(video);
      };
    });
  }

  if (STATE.estimate && Date.now() > lastEstimate.cooldown) {
    // Detector can be null if initialization failed (for example when loading from an URL that does not exist).
    if (detector != null && !lastEstimate.inProgress) {
      lastEstimate.inProgress = true;
      estimatePoses();
    }
  } else {
    lastEstimate.poses = [];
    if (lastEstimate.centerElem) lastEstimate.centerElem.innerHTML = STATE.estimate ? "Can't find enough keypoints" : "Estimation disabled";
  }

  // The null check makes sure the UI is not in the middle of changing to a different model.
  // If during model change, the result is from an old model, which shouldn't be rendered.
  if (lastEstimate.poses && !STATE.isModelChanged) {
    getTargetOrientation(lastEstimate.poses);
    correctPoseOrientation(lastEstimate.poses);
    const rendererParams = useGpuRenderer ?
      [camera.video, lastEstimate.poses, lastEstimate.canvasInfo, STATE.modelConfig.scoreThreshold] :
      [camera.video, lastEstimate.poses, STATE.isModelChanged];
    renderer.draw(rendererParams);
  }
  endEstimatePosesStats(renderResultStats);
}

async function renderPrediction() {
  await checkGuiUpdate();
  await manageDeviceOrientationHandler();
  if (!STATE.isModelChanged && STATE.render) await renderResult();
  rafId = requestAnimationFrame(renderPrediction);
};

export function getData() {
  return JSON.parse(JSON.stringify(STATE.calibration));
}

async function app() {
  // Gui content will change depending on which model is in the query string.
  const urlParams = new URLSearchParams(window.location.search);
  STATE.dev = urlParams.get('dev') === 'true';

  lastDeviceOrientation.statusElem = document.getElementById('status');
  lastEstimate.centerElem = document.getElementById('center');
  const estimatePosesStatsElem = document.getElementById('estimatePosesStats');
  const renderResultStatsElem = document.getElementById('renderResultStats');

  if (STATE.dev) STATE.camera.facingMode = 'user';
  else {
    estimatePosesStatsElem.style.display = 'none';
    renderResultStatsElem.style.display = 'none';
  }

  await setupDatGui();

  estimatePosesStats.customFpsPanel = setupStats(estimatePosesStatsElem, 'ESTIMATE', 0).customFpsPanel;
  renderResultStats.customFpsPanel = setupStats(renderResultStatsElem, 'RENDER', 1).customFpsPanel;

  const isWebGPU = STATE.backend === 'tfjs-webgpu';
  const importVideo = (urlParams.get('importVideo') === 'true') && isWebGPU;

  camera = await Camera.setup(STATE.camera);

  await setBackendAndEnvFlags(STATE.flags, STATE.backend);
  await tf.ready();
  detector = await createDetector();
  const canvas = document.getElementById('output');
  canvas.width = camera.video.width;
  canvas.height = camera.video.height;
  useGpuRenderer = (urlParams.get('gpuRenderer') === 'true') && isWebGPU;
  if (useGpuRenderer) {
    renderer = new RendererWebGPU(canvas, importVideo);
  } else {
    renderer = new RendererCanvas2d(canvas);
  }

  renderPrediction();
};

app();

if (useGpuRenderer) {
  renderer.dispose();
}
